// Preparar idea individual para redacción
const idea = $json;

return [{
  json: {
    idea_id: idea.id,
    idea_title: idea.idea_title,
    categoria: idea.categoria,
    keyword_cluster_id: idea.keyword_cluster_id,
    estimated_word_count: idea.estimated_word_count || 600,
    cluster_name: idea.cluster_name,
    keyword_principal: idea.keyword_principal,
    keywords_secundarias: idea.keywords_secundarias
  }
}];

// Construir Prompt #3 - Redacción Simple
const idea = $json.idea_title;
const wordCount = $json.estimated_word_count || 600;

const webhookItems = $items('Webhook', 0) || [];
const requestBody = (webhookItems[0]?.json?.body) || {};
const customPromptRaw = requestBody.article_prompt_override || requestBody.articlePromptOverride || null;

const keywordsSec = Array.isArray($json.keywords_secundarias) ? $json.keywords_secundarias : [];
const tokenMap = {
  idea_title: idea,
  idea,
  word_count: wordCount,
  cluster_name: $json.cluster_name || '',
  keyword_principal: $json.keyword_principal || '',
  keywords_secundarias: keywordsSec.join(', '),
  keywords: keywordsSec.join(', ')
};

const normalizeKey = (token) =>
  String(token || '')
    .replace(/([a-z])([A-Z])/g, '$1_$2')
    .replace(/[^a-z0-9_]/gi, '_')
    .toLowerCase();

const applyTokens = (template) => {
  if (!template) return '';
  return String(template).replace(/\{\{\s*([^}]+)\}\}/g, (_, rawKey) => {
    const key = normalizeKey(rawKey);
    return Object.prototype.hasOwnProperty.call(tokenMap, key)
      ? String(tokenMap[key] ?? '')
      : '';
  });
};

const basePrompt = `Actúa como un redactor profesional especializado en SEO.

Recibirás una idea de contenido clasificada como "No requiere investigación".

**Idea:** ${idea}

Tu tarea es redactar un artículo optimizado para SEO:

1. Usar la idea como título principal (H1)
2. Incluir párrafo introductorio breve y atractivo
3. Desarrollar contenido de al menos ${wordCount} palabras
4. Usar subtítulos (H2, H3) para organizar la información
5. Lenguaje claro, fluido y fácil de leer
6. Integrar keywords naturalmente si son evidentes
7. Conclusión con resumen o CTA cuando sea relevante
8. Contenido 100% original, sin plagio

**Metadatos SEO:**
- Meta Title: máximo 60 caracteres, atractivo, con keyword
- Meta Description: máximo 155 caracteres, persuasiva, invite al clic
- Tags: 5 a 8 etiquetas relevantes separadas por comas

**Formato de salida (Markdown con frontmatter):**
---
Meta Title: [Texto aquí]
Meta Description: [Texto aquí]
Tags: [tag1, tag2, tag3, ...]
---

# [Título del artículo]

[Párrafo introductorio...]

## [Subtítulo H2]
[Contenido de la sección...]

## [Subtítulo H2]
[Contenido de la sección...]

**Conclusión:** [Párrafo final con resumen...]

IMPORTANTE: 
- Responde SOLO con el Markdown completo, sin bloques de código.
- Asegúrate de incluir el frontmatter con los metadatos.
- El contenido debe tener al menos ${wordCount} palabras.`;

const prompt = customPromptRaw ? applyTokens(customPromptRaw) : basePrompt;

return [{
  json: {
    prompt,
    idea_id: $json.idea_id,
    idea_title: idea,
    keyword_cluster_id: $json.keyword_cluster_id,
    estimated_word_count: wordCount
  }
}];

// Parse Markdown Response (robusto)
let response = $json?.message?.content ?? $json?.text ?? $json?.response ?? '';
response = String(response).trim().replace(/\r\n/g, '\n'); // normaliza EOL

// Quitar fences solo si envuelven todo el contenido: ```lang\n ... \n```
const fenceMatch = response.match(/^```(\w+)?\s*\n([\s\S]*?)\n```$/);
if (fenceMatch) {
  response = fenceMatch[2].trim();
} else {
  // Si el provider a veces pone ``` al inicio sin lang o un cierre suelto
  if (response.startsWith('```')) response = response.replace(/^```\s*\n?/, '');
  if (response.endsWith('```')) response = response.replace(/\n?```\s*$/, '');
  response = response.trim();
}

// Toma el item emparejado que ENTRÓ a "Construir Prompt Redacción"
const src = ($items('Construir Prompt Redacción', 0)[$itemIndex]?.json) ?? {};

// Devuelve el markdown crudo + conserva campos de origen (idea_id, etc.)
return [{
  json: {
    ...src, // preserva idea_id, keyword_cluster_id y otros
    raw_markdown: response
  }
}];

// Extraer metadatos del frontmatter y contenido (robusto)

// 1) Normaliza entrada y fin de línea
const markdown = String($json.raw_markdown || '').replace(/\r\n/g, '\n');

// 2) Detecta front-matter tipo --- ... ---
const fm = markdown.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
let front = '', content = markdown;
if (fm) {
  front = fm[1].trim();
  content = fm[2] ?? '';
}

// 3) Parseo simple de "YAML" línea por línea (sin lib)
const meta = {};
if (front) {
  // Soporta "clave: valor" y listas con "- item"
  const lines = front.split('\n');
  let currentKey = null;
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;

    const kv = line.match(/^([A-Za-z0-9 _-]+)\s*:\s*(.*)$/);
    if (kv) {
      currentKey = kv[1].toLowerCase().trim();      // ej. "meta title"
      meta[currentKey] = kv[2];                      // resto de la línea (puede estar vacío)
      continue;
    }

    // Si es lista tipo "- item" y hay clave en curso, acumula
    const li = line.match(/^-\s+(.*)$/);
    if (li && currentKey) {
      const prev = meta[currentKey] || '';
      meta[currentKey] = (prev ? prev + '\n' : '') + li[1];
      continue;
    }

    // Soporta continuación de párrafos multi-línea
    if (currentKey) {
      meta[currentKey] = (meta[currentKey] ? meta[currentKey] + '\n' : '') + line;
    }
  }
}

// 4) Normaliza campos esperados
const get = (k) => meta[k] || meta[k.replace(/\s+/g,'')] || '';

let metaTitle = get('meta title') || get('title') || '';
let metaDescription = get('meta description') || get('description') || '';
let tagsRaw = get('tags');

// Admite tags como "a, b, c", listas con "- a", o "[a, b]"
let tags = [];
if (tagsRaw) {
  const normalized = tagsRaw
    .replace(/^\[/, '').replace(/\]$/, '')  // quita corchetes
    .split(/\n|,/);                          // separa por líneas o comas
  tags = normalized.map(t => t.trim()).filter(Boolean);
}

// 5) Título: primer H1 del contenido o metaTitle o idea_title
const h1 = content.match(/^#\s+(.+)\s*$/m);
const title = (h1 && h1[1].trim()) || metaTitle || ($json.idea_title || '').trim();

// 6) Fallbacks SEO
const clamp = (s, n) => (s.length <= n ? s : s.slice(0, n - 1).trimEnd() + '…');
if (!metaTitle) metaTitle = clamp(title || 'Sin título', 60);

// Si no hay description, toma primer párrafo del contenido
if (!metaDescription) {
  const plain = content
    .replace(/^---[\s\S]*?---\n/, '')    // por si quedara otro fm
    .replace(/^#+\s+.*$/gm, '')          // quita headers
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // links → texto
    .replace(/[*_~`#>]/g, '')            // formato
    .replace(/\n{2,}/g, '\n')
    .trim();
  const firstPara = plain.split('\n').find(p => p.trim());
  metaDescription = clamp(firstPara || 'Artículo generado automáticamente.', 160);
}

// 7) Salida: preserva TODO lo que venía (incl. UUIDs)
return [{
  json: {
    ...$json, // idea_id, keyword_cluster_id, idea_title, etc.
    title: title || 'Sin título',
    meta_title: metaTitle,
    meta_description: metaDescription,
    tags: Array.isArray(tags) ? tags : [],
    content_markdown: content.trim(),
    raw_markdown: markdown
  }
}];

// ---------- Recupera UUIDs por si se perdieron ----------
let idea_id = $json.idea_id;
let keyword_cluster_id = $json.keyword_cluster_id;

// Intenta reinyectarlos desde nodos previos por índice
const idx = $itemIndex;
const fromPrompt = $items('Construir Prompt Redacción', 0)[idx]?.json || {};
const fromParse  = $items('Parse Markdown Response', 0)[idx]?.json || {};
const fromMeta   = $items('Extraer Metadatos', 0)[idx]?.json || {};

idea_id = idea_id || fromMeta.idea_id || fromParse.idea_id || fromPrompt.idea_id;
keyword_cluster_id = keyword_cluster_id || fromMeta.keyword_cluster_id || fromParse.keyword_cluster_id || fromPrompt.keyword_cluster_id;

// ---------- Validaciones suaves ----------
const hasIds = !!idea_id && !!keyword_cluster_id;
const hasContent = typeof $json.content_markdown === 'string' && $json.content_markdown.trim().length > 0;

// Conteo
let word_count = 0;
if (hasContent) {
  const text = $json.content_markdown
    .replace(/^#+\s+/gm, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/[*_~`#>]/g, '')
    .replace(/^[->]\s+/gm, '')
    .trim();
  word_count = text ? text.split(/\s+/).filter(Boolean).length : 0;
}

// Señal de omisión
const skipReason = !hasIds ? 'missing_uuids' : (!hasContent ? 'missing_content' : null);

return [{
  json: {
    ...$json,
    idea_id,
    keyword_cluster_id,
    word_count,
    _skip: !!skipReason,
    _skip_reason: skipReason
  }
}];

// Preparar respuesta final con resumen
const drafts = $json.all_drafts || [];

return [{
  json: {
    status: 'success',
    total_ideas_processed: drafts.length,
    total_drafts_created: drafts.length,
    drafts_details: drafts.map(d => ({
      draft_id: d.id,
      idea_id: d.idea_id,
      title: d.title,
      word_count: d.word_count,
      meta_title: d.meta_title,
      tags_count: d.tags?.length || 0,
      created_at: d.created_at
    })),
    processing_time: new Date().toISOString()
  }
}];

// No hay ideas pendientes sin investigación
return [{
  json: {
    status: 'info',
    message: 'No hay ideas pendientes sin investigación para redactar',
    total_ideas_processed: 0,
    total_drafts_created: 0,
    drafts_details: []
  }
}];
